{"content":"import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import QRCode from 'qrcode';
import './styles.css';

type Friend = {
  code: string;
  nickname: string;
  addedAt: string;
};

const STORAGE_KEY = 'trainer-qr-friends-v1';

function normalizeCode(value: string) {
  return value.replace(/\D/g, '').slice(0, 12);
}

function formatCode(value: string) {
  const digits = normalizeCode(value);
  return digits.replace(/(\d{4})(?=\d)/g, '$1 ').trim();
}

function isValidCode(value: string) {
  return normalizeCode(value).length === 12;
}

function App() {
  const [myCode, setMyCode] = useState('');
  const [scanCode, setScanCode] = useState('');
  const [nickname, setNickname] = useState('');
  const [friends, setFriends] = useState<Friend[]>([]);
  const [qrDataUrl, setQrDataUrl] = useState('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return;
    try {
      setFriends(JSON.parse(raw));
    } catch {
      window.localStorage.removeItem(STORAGE_KEY);
    }
  }, []);

  useEffect(() => {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(friends));
  }, [friends]);

  useEffect(() => {
    const code = normalizeCode(myCode);
    if (!isValidCode(code)) {
      setQrDataUrl('');
      return;
    }
    QRCode.toDataURL(code, {
      margin: 2,
      width: 360,
      color: { dark: '#111827', light: '#ffffff' },
      errorCorrectionLevel: 'M'
    }).then(setQrDataUrl);
  }, [myCode]);

  const validMyCode = isValidCode(myCode);
  const validScanCode = isValidCode(scanCode);

  const friendCount = friends.length;
  const uniqueCodes = useMemo(() => new Set(friends.map((f) => f.code)).size, [friends]);

  function addFriend() {
    const code = normalizeCode(scanCode);
    if (!isValidCode(code)) return;
    setFriends((current) => {
      const withoutDuplicate = current.filter((friend) => friend.code !== code);
      return [
        {
          code,
          nickname: nickname.trim() || 'Trainer',
          addedAt: new Date().toISOString()
        },
        ...withoutDuplicate
      ];
    });
    setScanCode('');
    setNickname('');
  }

  async function copyMyCode() {
    if (!validMyCode) return;
    await navigator.clipboard.writeText(formatCode(myCode));
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  }

  function clearFriends() {
    setFriends([]);
    window.localStorage.removeItem(STORAGE_KEY);
  }

  return (
    <main className="shell">
      <section className="hero panel">
        <div>
          <p className="eyebrow">unofficial trainer utility</p>
          <h1>Trainer QR Trade Board</h1>
          <p className="lede">
            Generate a scannable friend-code QR, log trainers you meet, and keep everything local on your device.
          </p>
        </div>
        <div className="status-grid" aria-label="MVP status">
          <div><strong>{validMyCode ? 'Ready' : 'Input'}</strong><span>QR state</span></div>
          <div><strong>{friendCount}</strong><span>saved</span></div>
          <div><strong>{uniqueCodes}</strong><span>unique</span></div>
        </div>
      </section>

      <section className="grid">
        <article className="panel card-primary">
          <div className="section-head">
            <p className="eyebrow">01 / Generate</p>
            <h2>Your friend code</h2>
          </div>
          <label className="field">
            <span>12-digit friend code</span>
            <input
              inputMode="numeric"
              placeholder="1234 5678 9012"
              value={formatCode(myCode)}
              onChange={(event) => setMyCode(normalizeCode(event.target.value))}
              aria-invalid={myCode.length > 0 && !validMyCode}
            />
          </label>
          <div className="qr-frame">
            {qrDataUrl ? (
              <img src={qrDataUrl} alt={`QR code for trainer code ${formatCode(myCode)}`} />
            ) : (
              <div className="qr-empty">enter 12 digits</div>
            )}
          </div>
          <div className="action-row">
            <button disabled={!validMyCode} onClick={copyMyCode}>{copied ? 'Copied' : 'Copy code'}</button>
            <a className={qrDataUrl ? 'button ghost' : 'button ghost disabled'} href={qrDataUrl || undefined} download="trainer-friend-code.png">Download QR</a>
          </div>
        </article>

        <article className="panel">
          <div className="section-head">
            <p className="eyebrow">02 / Simulate scan</p>
            <h2>Add a trainer</h2>
          </div>
          <label className="field">
            <span>Nickname</span>
            <input placeholder="Gym rival, raid buddy…" value={nickname} onChange={(event) => setNickname(event.target.value)} />
          </label>
          <label className="field">
            <span>Scanned/manual friend code</span>
            <input
              inputMode="numeric"
              placeholder="0000 0000 0000"
              value={formatCode(scanCode)}
              onChange={(event) => setScanCode(normalizeCode(event.target.value))}
              aria-invalid={scanCode.length > 0 && !validScanCode}
            />
          </label>
          <button className="full" disabled={!validScanCode} onClick={addFriend}>Add to local list</button>

          <div className="friend-list" aria-live="polite">
            <div className="list-head">
              <h3>Local friend queue</h3>
              {friends.length > 0 && <button className="text-button" onClick={clearFriends}>clear</button>}
            </div>
            {friends.length === 0 ? (
              <p className="muted">No trainers saved yet. Add one manually after a scan.</p>
            ) : (
              friends.map((friend) => (
                <div className="friend" key={friend.code}>
                  <div>
                    <strong>{friend.nickname}</strong>
                    <span>{new Date(friend.addedAt).toLocaleDateString()}</span>
                  </div>
                  <code>{formatCode(friend.code)}</code>
                </div>
              ))
            )}
          </div>
        </article>
      </section>

      <section className="panel disclaimer">
        <strong>Privacy + disclaimer:</strong> This MVP stores friend codes only in your browser localStorage. It is not affiliated with Niantic, Pokémon, Nintendo, or The Pokémon Company. Do not share personal info or meet strangers without basic safety rules.
      </section>
    </main>
  );
}

createRoot(document.getElementById('root')!).render(<App />);
