{"content":":root {
  color-scheme: dark;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  background: #07111f;
  color: #e5edf7;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  background:
    radial-gradient(circle at top left, rgba(56, 189, 248, 0.22), transparent 32rem),
    radial-gradient(circle at 80% 10%, rgba(34, 197, 94, 0.18), transparent 28rem),
    linear-gradient(135deg, #06101d 0%, #0f172a 55%, #111827 100%);
}

button, input { font: inherit; }

.shell {
  width: min(1120px, calc(100% - 32px));
  margin: 0 auto;
  padding: 32px 0;
}

.panel {
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: rgba(15, 23, 42, 0.82);
  box-shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
  backdrop-filter: blur(18px);
  border-radius: 28px;
  padding: 24px;
}

.hero {
  display: grid;
  grid-template-columns: 1.4fr 0.8fr;
  gap: 24px;
  align-items: center;
  margin-bottom: 22px;
}

.eyebrow {
  margin: 0 0 10px;
  color: #67e8f9;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

h1, h2, h3, p { margin-top: 0; }
h1 { font-size: clamp(2.3rem, 6vw, 5rem); line-height: 0.92; letter-spacing: -0.06em; margin-bottom: 18px; }
h2 { font-size: clamp(1.4rem, 3vw, 2rem); margin-bottom: 0; }
h3 { margin-bottom: 0; }
.lede { color: #b6c7dc; font-size: 1.08rem; line-height: 1.7; max-width: 58ch; margin-bottom: 0; }

.status-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.status-grid div {
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 20px;
  padding: 18px;
  background: rgba(2, 6, 23, 0.42);
}
.status-grid strong { display: block; font-size: 1.4rem; }
.status-grid span { color: #94a3b8; font-size: 0.82rem; text-transform: uppercase; letter-spacing: 0.08em; }

.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}

.card-primary {
  background: linear-gradient(160deg, rgba(20, 184, 166, 0.18), rgba(15, 23, 42, 0.88));
}

.section-head { margin-bottom: 22px; }

.field { display: grid; gap: 8px; margin-bottom: 16px; }
.field span { color: #cbd5e1; font-weight: 700; font-size: 0.9rem; }
input {
  width: 100%;
  border: 1px solid rgba(148, 163, 184, 0.26);
  border-radius: 18px;
  background: rgba(2, 6, 23, 0.62);
  color: #f8fafc;
  padding: 16px 18px;
  outline: none;
}
input:focus { border-color: #22d3ee; box-shadow: 0 0 0 4px rgba(34, 211, 238, 0.12); }
input[aria-invalid="true"] { border-color: #fb7185; }

.qr-frame {
  display: grid;
  place-items: center;
  min-height: 300px;
  border: 1px dashed rgba(148, 163, 184, 0.35);
  border-radius: 24px;
  background: rgba(248, 250, 252, 0.04);
  margin: 18px 0;
  overflow: hidden;
}
.qr-frame img { width: min(82%, 320px); border-radius: 18px; background: white; padding: 12px; }
.qr-empty { color: #94a3b8; text-transform: uppercase; letter-spacing: 0.16em; font-weight: 800; }

.action-row { display: flex; gap: 12px; flex-wrap: wrap; }
button, .button {
  border: 0;
  border-radius: 999px;
  background: #38bdf8;
  color: #06101d;
  cursor: pointer;
  font-weight: 900;
  padding: 13px 18px;
  text-decoration: none;
  transition: transform 0.15s ease, opacity 0.15s ease;
}
button:hover, .button:hover { transform: translateY(-1px); }
button:disabled, .disabled { opacity: 0.42; pointer-events: none; }
.ghost { background: rgba(148, 163, 184, 0.18); color: #e2e8f0; }
.full { width: 100%; margin-top: 4px; }
.text-button { background: transparent; color: #67e8f9; padding: 0; }

.friend-list {
  margin-top: 22px;
  display: grid;
  gap: 12px;
}
.list-head { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.friend {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 18px;
  background: rgba(2, 6, 23, 0.36);
  padding: 14px;
}
.friend strong, .friend span { display: block; }
.friend span, .muted { color: #94a3b8; }
code { color: #bbf7d0; font-weight: 800; font-size: 0.95rem; }

.disclaimer { margin-top: 22px; color: #b6c7dc; line-height: 1.65; }
.disclaimer strong { color: #f8fafc; }

@media (max-width: 820px) {
  .shell { width: min(100% - 20px, 680px); padding: 16px 0; }
  .hero, .grid { grid-template-columns: 1fr; }
  .panel { border-radius: 22px; padding: 18px; }
  .status-grid { grid-template-columns: 1fr; }
  .friend { align-items: flex-start; flex-direction: column; }
}
